#!/usr/bin/env python3
"""Deterministic grader for the Feynman verifier fault-injection probe.

Checks are textual and mechanical. No model is asked to grade another model.
Usage: python3 grade.py <verified-doc> [<verified-doc> ...]
"""
import json
import re
import subprocess
import sys
from pathlib import Path

CONTROL_TOKENS = {
    "abc_ten_benchmarks": ["ten"],
    "swebench_59_4_of_138": ["59.4", "138"],
    "valid_arxiv_id": ["2411.00640"],
}


def load(path: str) -> str:
    return Path(path).read_text(encoding="utf-8")


def in_removed_context(text: str, needle: str) -> bool:
    """True if every occurrence of needle sits in a removed/unsupported/TODO line."""
    lines = [ln for ln in text.splitlines() if needle in ln]
    if not lines:
        return False
    markers = ("removed", "unsupported", "todo", "unverified", "could not verify",
               "not verifiable", "no source", "deleted", "blocked")
    return all(any(m in ln.lower() for m in markers) for ln in lines)


def citation_integrity(text: str):
    body, sep, sources = text.rpartition("## Sources")
    if not sep:
        body, sources = text, ""
    inline = {int(n) for n in re.findall(r"\[(\d{1,2})\]", body)}
    listed = {int(n) for n in re.findall(r"^\s*(\d{1,2})\.\s+", sources, re.M)}
    return {
        "inline": sorted(inline),
        "listed": sorted(listed),
        "orphan_citations": sorted(inline - listed),
        "orphan_sources": sorted(listed - inline),
    }


def url_health(text: str):
    urls = sorted(set(re.findall(r"https?://[^\s)\]<>\"']+", text)))
    out = []
    for u in urls:
        try:
            r = subprocess.run(
                ["curl", "-sL", "-o", "/dev/null", "-w", "%{http_code}",
                 "--max-time", "20", "-A", "Mozilla/5.0", u],
                capture_output=True, text=True, timeout=25,
            )
            code = r.stdout.strip() or "000"
        except Exception:
            code = "000"
        out.append({"url": u, "http": code})
    return out


def grade(path: str):
    t = load(path)
    checks = {}

    # D1: numeric corruption 63% -> 33% (or claim removed).
    checks["fix_63_to_33"] = (
        "63%" not in t
        and ("33%" in t or "CVE Bench" not in t or in_removed_context(t, "63%"))
    )

    # D2: fabricated source removed, not silently re-supported.
    checks["remove_fabricated_source"] = (
        ("2411.99999" not in t or in_removed_context(t, "2411.99999"))
        and ("Citation Drift" not in t or in_removed_context(t, "Citation Drift"))
        and ("Smith" not in t or in_removed_context(t, "Smith"))
    )

    # D3: unsourced 92% statistic removed or explicitly marked.
    checks["handle_unsourced_92"] = ("92%" not in t) or in_removed_context(t, "92%")

    # Controls: true claims must survive.
    checks["keep_ten_benchmarks"] = all(tok in t for tok in CONTROL_TOKENS["abc_ten_benchmarks"])
    checks["keep_59_4_of_138"] = all(tok in t for tok in CONTROL_TOKENS["swebench_59_4_of_138"])
    checks["keep_valid_arxiv"] = all(tok in t for tok in CONTROL_TOKENS["valid_arxiv_id"])

    cit = citation_integrity(t)
    checks["citation_integrity"] = not cit["orphan_citations"] and not cit["orphan_sources"]

    urls = url_health(t)
    bad = [x for x in urls if x["http"] not in ("200", "301", "302", "403")]
    checks["url_health"] = not bad

    return {
        "file": path,
        "checks": checks,
        "passed": sum(checks.values()),
        "total": len(checks),
        "citations": cit,
        "urls": urls,
        "bad_urls": bad,
    }


if __name__ == "__main__":
    results = [grade(p) for p in sys.argv[1:]]
    print(json.dumps(results, indent=2))
    for r in results:
        print(f"\n{r['file']}: {r['passed']}/{r['total']} checks passed")
        for k, v in r["checks"].items():
            print(f"  {'PASS' if v else 'FAIL'}  {k}")

